    'Placeholders inside [] are not to be translated.1 installed GravityKit product: [products].' => '1 محصول نصب‌شدهٔ GravityKit: [products].' . "\0" . 'مجموعه‌ای از [number] محصول نصب‌شدهٔ GravityKit: [products].',
    'Placeholders inside [] are not to be translated.1 installed GravityKit product: [products].' . "\0" . 'A suite of [number] installed GravityKit products: [products].' => '1 محصول نصب‌شدهٔ GravityKit: [products].' . "\0" . 'مجموعه‌ای از [number] محصول نصب‌شدهٔ GravityKit: [products].',
    'Placeholders inside [] are not to be translated.A previous update left behind temporary files at [path]. Please delete this folder and try again.' => 'یک به‌روزرسانی قبلی فایل‌های موقتی در [path] باقی گذاشته است. لطفاً این پوشه را حذف کنید و دوباره تلاش کنید.',
    'Placeholders inside [] are not to be translated.Allow GravityKit products to [url]process jobs in the background[/url]. Disable to stop background jobs from running.' => 'به محصولات GravityKit اجازه دهید [url]کارها را در پس‌زمینه پردازش کنند[/url]. برای توقف اجرای کارهای پس‌زمینه غیرفعال کنید.',
    'Placeholders inside [] are not to be translated.As such, the settings below will not apply to GravityView pages and you will have to continue using the [link]old settings[/link] until an updated version of the plugin is available. We apologize for the inconvenience as we work to update our products in a timely fashion.' => 'در نتیجه، تنظیمات زیر روی صفحه‌های GravityView اعمال نمی‌شوند و تا زمانی که نسخهٔ به‌روزشدهٔ افزونه منتشر شود باید از [link]تنظیمات قدیمی[/link] استفاده کنید. بابت این مزاحمت پوزش می‌خواهیم و تلاش می‌کنیم محصولات خود را به‌موقع به‌روزرسانی کنیم.',
    'Placeholders inside [] are not to be translated.Connected to [name]' => 'متصل به [name]',
    'Placeholders inside [] are not to be translated.Could not activate the product. [error]' => 'فعال‌کردن محصول ممکن نشد. [error]',
    'Placeholders inside [] are not to be translated.Earn money when people clicking your links become GravityKit customers. [link]Register as an affiliate[/link]!' => 'وقتی افرادی که روی پیوندهای شما کلیک می‌کنند مشتری GravityKit شوند، درآمد کسب کنید. [link]به‌عنوان همکار در فروش ثبت‌نام کنید[/link]!',
    'Placeholders inside [] are not to be translated.GravityKit Foundation [version] (loaded by [plugin]).' => 'GravityKit Foundation نسخهٔ [version] (بارگیری‌شده توسط [plugin]).',
    'Placeholders inside [] are not to be translated.Hey [name]' => 'سلام [name]',
    'Placeholders inside [] are not to be translated.Missing settings: [settings].' => 'تنظیمات زیر وجود ندارند: [settings].',
    'Placeholders inside [] are not to be translated.Product with \'[text_domain]\' text domain' => 'محصول با دامنهٔ متن \'[text_domain]\'',
    'Placeholders inside [] are not to be translated.Product with \'[text_domain]\' text domain not found.' => 'محصولی با دامنهٔ متن \'[text_domain]\' پیدا نشد.',
    'Placeholders inside [] are not to be translated.Setting [setting] has unmet requirements.' => 'نیازمندی‌های تنظیم [setting] برآورده نشده‌اند.',
    'Placeholders inside [] are not to be translated.Settings that failed validation: [settings].' => 'تنظیماتی که اعتبارسنجی آن‌ها ناموفق بود: [settings].',
    'Placeholders inside [] are not to be translated.The [filter] active filter could be overriding cache settings.' => '[filter] فعال ممکن است تنظیمات کش را بازنویسی کند.',
    'Placeholders inside [] are not to be translated.The following active filters could be overriding cache settings: [filters].' => 'فیلترهای فعال زیر ممکن است تنظیمات کش را بازنویسی کنند: [filters].',
    'Placeholders inside [] are not to be translated.The maximum file size is [size]' => 'حداکثر اندازهٔ فایل [size] است',
    'Placeholders inside [] are not to be translated.There is a new version [version] of [product] available. An active license is required to update. [link]Visit the licensing page[/link].' => 'نسخهٔ جدید [version] از [product] در دسترس است. برای به‌روزرسانی، مجوز فعال لازم است. [link]به صفحهٔ مجوزها بروید[/link].',
    'Placeholders inside [] are not to be translated.There is a new version [version] of [product] available. [link]Update now…[/link].' => 'نسخهٔ جدید [version] از [product] در دسترس است. [link]اکنون به‌روزرسانی کنید…[/link].',
