    'Task failed (sentinel).' => 'وظیفه ناموفق بود (نگهبان).',
    'Technical' => 'فنی',
    'Template (layout) id from gk-gravityview/layouts-list (e.g. "default_list", "default_table", "gravityview-layout-builder").' => 'id قالب (چیدمان) از gk-gravityview/layouts-list (برای نمونه "default_list"، "default_table"، "gravityview-layout-builder").',
    'Template id (use as template_id when creating/switching a View).' => 'id قالب (هنگام ایجاد/تغییر چیدمان نما به‌عنوان template_id استفاده کنید).',
